def configure_fonts(root: tk.Misc) -> None:
    """Use the platform's native UI font, with Apple-friendly fallbacks."""

    global UI_FAMILY
    global MONO_FAMILY
    global FONT_TITLE
    global FONT_SUBTITLE
    global FONT_SECTION
    global FONT_BODY
    global FONT_BODY_BOLD
    global FONT_SMALL
    global FONT_SMALL_BOLD
    global FONT_MONO
    global FONT_MONO_SMALL

    families = set(tkfont.families(root))

    default_family = tkfont.nametofont(
        "TkDefaultFont"
    ).actual("family")

    fixed_family = tkfont.nametofont(
        "TkFixedFont"
    ).actual("family")

    ui_candidates = (
        "SF Pro Text",
        "SF Pro Display",
        "Helvetica Neue",
        "Avenir Next",
        default_family,
    )

    mono_candidates = (
        "SF Mono",
        "Menlo",
        "Monaco",
        fixed_family,
    )

    UI_FAMILY = next(
        (
            family
            for family in ui_candidates
            if family in families
        ),
        default_family,
    )

    MONO_FAMILY = next(
        (
            family
            for family in mono_candidates
            if family in families
        ),
        fixed_family,
    )

    FONT_TITLE = (UI_FAMILY, 32, "bold")
    FONT_SUBTITLE = (UI_FAMILY, 14)
    FONT_SECTION = (UI_FAMILY, 18, "bold")
    FONT_BODY = (UI_FAMILY, 14)
    FONT_BODY_BOLD = (UI_FAMILY, 14, "bold")
    FONT_SMALL = (UI_FAMILY, 12)
    FONT_SMALL_BOLD = (UI_FAMILY, 12, "bold")
    FONT_MONO = (MONO_FAMILY, 12)
    FONT_MONO_SMALL = (MONO_FAMILY, 11)


