def center_window(
    window: tk.Misc,
    width: int,
    height: int,
) -> None:
    """Center the application on the current display without maximizing it."""

    window.update_idletasks()

    screen_width = window.winfo_screenwidth()
    screen_height = window.winfo_screenheight()

    width = min(
        width,
        max(760, screen_width - 120),
    )

    height = min(
        height,
        max(620, screen_height - 140),
    )

    x = max(
        0,
        int((screen_width - width) / 2),
    )

    y = max(
        0,
        int((screen_height - height) / 2),
    )

    window.geometry(
        f"{width}x{height}+{x}+{y}"
    )


def humanize(name: str) -> str:
    return name.replace("_", " ").title()


