class QueueStream(io.TextIOBase):
    """Thread-safe stream adapter for print() and tqdm."""

    def __init__(
        self,
        target_queue: queue.Queue,
        stream_name: str,
    ):
        super().__init__()
        self.target_queue = target_queue
        self.stream_name = stream_name

    def writable(self):
        return True

    def write(self, data):
        if data:
            self.target_queue.put(
                (
                    "stream",
                    self.stream_name,
                    str(data),
                )
            )
        return len(data)

    def flush(self):
        return None


