    def _spatial_dimension_changed(self, dimension=None):
        dimension = (
            dimension
            or self.spatial_dimension_var.get()
        ).strip().lower()

        if dimension not in {
            "2d",
            "3d",
        }:
            dimension = "2d"
            self.spatial_dimension_var.set(
                dimension
            )

        if dimension == "3d":
            self.spatial_dimension_note_var.set(
                "Use 3D for Z-stacks or volumetric images. "
                "Not available in this release."
            )

        else:
            self.spatial_dimension_note_var.set(
                "Use 2D when each image represents one XY plane."
            )


    def _input_mode_changed(self, mode=None, *, force_preprocessing=True):
        mode = (mode or self.input_mode_var.get()).strip().lower()

        if mode not in {"raw", "binary", "labels"}:
            mode = "binary"
            self.input_mode_var.set(mode)

        # MG_RAW_PRESET_VISIBILITY_V1
        #
        # Raw uses one of the built-in preprocessing recipes.
        # Binary and Labels bypass raw preprocessing, so the control is
        # hidden completely for those modes.
        if hasattr(
            self,
            "preprocessing_preset_selector",
        ):

            if mode == "raw":

                if (
                    not self.preprocessing_preset_label
                    .winfo_manager()
                ):
                    self.preprocessing_preset_label.pack(
                        side="left",
                        padx=(8, 5),
                    )

                if (
                    not self.preprocessing_preset_selector
                    .winfo_manager()
                ):
                    self.preprocessing_preset_selector.pack(
                        side="left",
                        padx=(0, 8),
                    )

            else:

                self.preprocessing_preset_label.pack_forget()
                self.preprocessing_preset_selector.pack_forget()


        if mode == "raw":
            self.input_mode_note_var.set(
                "Use for raw images that require preprocessing before segmentation. Built-in preprocessing; verification recommended."
            )
            self.binary_polarity_row.pack_forget()
            if (
                force_preprocessing
                and hasattr(self, "stage_vars")
                and "preprocessing" in self.stage_vars
            ):
                self.stage_vars["preprocessing"].set(True)

        elif mode == "labels":
            self.input_mode_note_var.set(
                "Use when your images already contain individual cell labels."
            )
            self.binary_polarity_row.pack_forget()
            self.invert_var.set(False)

        
        else:
            self.input_mode_note_var.set(
                "Use for binary images with cells separated from the background."
            )
            if not self.binary_polarity_row.winfo_ismapped():
                self.binary_polarity_row.pack(fill="x", pady=7)

