    def _refresh_morphology_state_options(self, output_dir=None):
        if not hasattr(self, "morphology_state_selector"):
            return

        previous_decision_path = getattr(
            self, "morphology_state_decision_path", None
        )
        previous_value = self.morphology_state_value_map.get(
            self.morphology_state_var.get()
        )
        if output_dir is None:
            raw_input = self.input_dir_var.get().strip()
            if not raw_input:
                decision_path = None
            else:
                decision_path = (
                    Path(raw_input).expanduser()
                    / "_MorphoGlia"
                    / "Dimensionality_Reduction_Clustering"
                    / "Decision"
                    / "resolution_decision.csv"
                )
        else:
            decision_path = (
                Path(output_dir)
                / "Dimensionality_Reduction_Clustering"
                / "Decision"
                / "resolution_decision.csv"
            )

        current_decision_path = (
            str(decision_path.expanduser().resolve())
            if decision_path is not None
            else None
        )
        if current_decision_path != previous_decision_path:
            previous_value = None
        self.morphology_state_decision_path = current_decision_path

        if decision_path is None or not decision_path.is_file():
            prompt = "First run — automatic"
            self.morphology_state_value_map = {prompt: None}
            self.morphology_state_selector.configure(values=(prompt,), state="disabled")
            self.morphology_state_var.set(prompt)
            self.morphology_state_note_var.set(
                "First run: MorphoGlia will estimate the stable numbers of "
                "morphology states automatically. \n"
                "After Dimensionality Reduction and Clustering has been run, or if this folder already contains those results, \n"
                "the stable choices will appear here."
            )
            return

        try:
            with decision_path.open("r", encoding="utf-8", newline="") as handle:
                rows = list(csv.DictReader(handle))

            truthy = {"1", "true", "yes"}
            supported = sorted(
                int(row["k"])
                for row in rows
                if str(row.get("supported_resolution", "")).strip().lower() in truthy
            )
            automatic_rows = [
                row for row in rows
                if str(row.get("automatic_selection", "")).strip().lower() in truthy
            ]
            if not automatic_rows:
                automatic_rows = [
                    row for row in rows
                    if str(row.get("default_resolution", "")).strip().lower() in truthy
                ]
            if not automatic_rows:
                automatic_rows = [
                    row for row in rows
                    if str(row.get("decision_role", "")).strip() == "preferred"
                ]
            if not supported or len(automatic_rows) != 1:
                raise ValueError("incomplete morphology-state decision table")
            automatic_count = int(automatic_rows[0]["k"])
            if automatic_count not in supported:
                raise ValueError("automatic count is not supported")
        except Exception as exc:
            prompt = "Clustering results need refresh"
            self.morphology_state_value_map = {prompt: None}
            self.morphology_state_selector.configure(values=(prompt,), state="disabled")
            self.morphology_state_var.set(prompt)
            self.morphology_state_note_var.set(
                "MorphoGlia found previous clustering output, but could not "
                "read the available morphology-state choices. Rerun Dimensionality "
                f"Reduction and Clustering for this dataset. Details: {exc}"
            )
            return

        automatic_label = f"Automatic ({automatic_count} states)"
        value_map = {automatic_label: None}
        for count in supported:
            value_map[f"{count} states"] = count

        labels = tuple(value_map)
        self.morphology_state_value_map = value_map
        self.morphology_state_selector.configure(values=labels, state="readonly")
        matching = next(
            (label for label, value in value_map.items() if value == previous_value),
            automatic_label,
        )
        self.morphology_state_var.set(matching)
        self.morphology_state_note_var.set(
            "Previous clustering results found. Choose Automatic to use "
            "MorphoGlia's data-driven selection, or choose one of the stable "
            "state counts found in that run. Changing this choice reuses the "
            "saved clustering results. Available: "
            + ", ".join(str(count) for count in supported)
            + " states."
        )

