    def _add_custom_field(self):
        row_frame = tk.Frame(
            self.custom_rows_frame,
            bg=CARD_SOFT,
            highlightthickness=1,
            highlightbackground=BORDER,
        )
        row_frame.pack(
            fill="x",
            pady=3,
        )

        name_var = tk.StringVar()
        position_var = tk.StringVar(
            value=NOT_USED
        )

        name_entry = tk.Entry(
            row_frame,
            textvariable=name_var,
            bg="#FFFFFF",
            fg=TEXT,
            insertbackground=TEXT,
            relief="flat",
            font=FONT_BODY,
            highlightthickness=0,
        )
        name_entry.pack(
            side="left",
            fill="x",
            expand=True,
            ipady=7,
            padx=(10, 8),
            pady=5,
        )

        combo = ttk.Combobox(
            row_frame,
            textvariable=position_var,
            values=[NOT_USED] + [
                str(i)
                for i in range(
                    1,
                    MIN_METADATA_POSITIONS + 1,
                )
            ],
            state="readonly",
            width=11,
            style="MG.TCombobox",
        )
        combo.pack(
            side="left",
            padx=4,
            pady=5,
        )

        item = {
            "frame": row_frame,
            "name_var": name_var,
            "position_var": position_var,
            "combo": combo,
        }

        def remove():
            if row_frame.winfo_exists():
                row_frame.destroy()

            self.custom_rows[:] = [
                candidate
                for candidate in self.custom_rows
                if candidate is not item
            ]

            self._metadata_changed()

        ArcadeButton(
            row_frame,
            text="×",
            command=remove,
            accent=RED,
            width=2,
            compact=True,
        ).pack(
            side="left",
            padx=(6, 8),
            pady=5,
        )

        self.custom_rows.append(item)

        name_var.trace_add(
            "write",
            lambda *_: self._metadata_changed(),
        )

        combo.bind(
            "<<ComboboxSelected>>",
            lambda event: self._metadata_changed(),
        )

        self._refresh_position_values()

    def _metadata_changed(self):
        if not self.root.winfo_exists():
            return

        self._refresh_position_values()
        self._refresh_filename_preview()
        self._refresh_categories()

    def _discover_images(self):
        raw = self.input_dir_var.get().strip()

        if not raw:
            return []

        directory = Path(raw).expanduser()

        if not directory.is_dir():
            return []

        return sorted(
            [
                path
                for path in directory.iterdir()
                if (
                    path.is_file()
                    and path.suffix.lower()
                    in IMAGE_EXTENSIONS
                )
            ],
            key=lambda path: path.name.lower(),
        )

    def _observed_position_count(self):
        images = self._discover_images()
        separator = self.separator_var.get()

        if not images or not separator:
            return 0

        counts = [
            len(path.stem.split(separator))
            for path in images[:50]
        ]

        return max(counts) if counts else 0

    def _refresh_position_values(self):
        if not hasattr(self, "position_combos"):
            return

        observed = self._observed_position_count()
        max_position = max(
            MIN_METADATA_POSITIONS,
            observed,
        )

        values = [NOT_USED] + [
            str(i)
            for i in range(1, max_position + 1)
        ]

        for combo in self.position_combos.values():
            if not combo.winfo_exists():
                continue

            current = combo.get()
            combo.configure(values=values)

            if (
                current != NOT_USED
                and current not in values
            ):
                combo.set(NOT_USED)

        for item in getattr(self, "custom_rows", []):
            combo = item["combo"]

            if not combo.winfo_exists():
                continue

            current = combo.get()
            combo.configure(values=values)

            if (
                current != NOT_USED
                and current not in values
            ):
                combo.set(NOT_USED)

    def _active_metadata(self):
        active = {}

        for field, var in self.metadata_vars.items():
            value = var.get()

            if value and value != NOT_USED:
                active[field] = int(value)

        custom = {}

        for item in self.custom_rows:
            if not item["frame"].winfo_exists():
                continue

            name = item["name_var"].get().strip()
            position = item["position_var"].get()

            if (
                name
                and position
                and position != NOT_USED
            ):
                custom[name] = int(position)

        return active, custom

    def _validate_metadata_mapping(self):
        active, custom = self._active_metadata()

        all_positions = list(
            active.values()
        ) + list(custom.values())

        duplicates = sorted(
            {
                position
                for position in all_positions
                if all_positions.count(position) > 1
            }
        )

        if duplicates:
            raise ValueError(
                "Each filename position can map to only one metadata field. "
                f"Duplicated position(s): {duplicates}"
            )

        normalized_custom = [
            name.strip().lower()
            for name in custom
        ]

        if len(normalized_custom) != len(
            set(normalized_custom)
        ):
            raise ValueError(
                "Custom metadata field names must be unique."
            )

        canonical_lower = {
            field.lower()
            for field in CANONICAL_METADATA
        }

        conflicts = [
            name
            for name in custom
            if name.lower() in canonical_lower
        ]

        if conflicts:
            raise ValueError(
                "Custom metadata fields cannot duplicate canonical fields: "
                f"{conflicts}"
            )

        return active, custom

    def _canonical_preview_key(self, field_name: str) -> str:
        if field_name in CANONICAL_KEYS:
            return CANONICAL_KEYS[field_name]
        return "".join(
            character.lower()
            for character in field_name
            if character.isalnum()
        ) or "field"

    def _preview_records(self):
        images = self._discover_images()
        separator = self.separator_var.get()
        active, custom = self._active_metadata()
        assignments = {**active, **custom}
        records = []

        if not separator:
            return images, assignments, records

        for path in images:
            tokens = path.stem.split(separator)
            values = {}
            valid = bool(assignments)

            for field, position in assignments.items():
                if 1 <= position <= len(tokens):
                    values[field] = tokens[position - 1]
                else:
                    valid = False

            records.append(
                {
                    "path": path,
                    "tokens": tokens,
                    "values": values,
                    "valid": valid,
                }
            )

        return images, assignments, records

    def _refresh_filename_preview(self):
        if not hasattr(self, "preview_raw_var"):
            return

        images, assignments, records = self._preview_records()
        separator = self.separator_var.get()

        if not images:
            self.preview_raw_var.set("Choose an input folder to inspect filenames.")
            self.preview_summary_var.set("Assign metadata positions after choosing a folder.")
            self.preview_example_var.set("")
            return

        raw_lines = [f"{len(images)} image file(s)", ""]
        raw_lines.extend(path.name for path in images[:6])
        if len(images) > 6:
            raw_lines.append(f"+ {len(images) - 6} more")
        self.preview_raw_var.set("\n".join(raw_lines))

        if not separator:
            self.preview_summary_var.set("Enter a filename separator.")
            self.preview_example_var.set("")
            return

        if not assignments:
            self.preview_summary_var.set(
                "No metadata fields are assigned yet.\n\nChoose a position for only the fields present in the filenames."
            )
            first = images[0]
            self.preview_example_var.set(f"{first.name}  →  no metadata assigned")
            return

        matched = sum(1 for record in records if record["valid"])
        summary_lines = [f"Matched: {matched} / {len(images)} files", ""]

        for field, position in assignments.items():
            counts = Counter(
                record["values"][field]
                for record in records
                if field in record["values"]
            )
            values = sorted(counts.items(), key=lambda item: str(item[0]).lower())
            shown = values[:6]
            rendered = ", ".join(
                f"{value} ({count})"
                for value, count in shown
            ) or "no matches"
            if len(values) > 6:
                rendered += f", +{len(values) - 6} more"

            summary_lines.append(f"{humanize(field)} · position {position}")
            summary_lines.append(rendered)
            summary_lines.append("")

        self.preview_summary_var.set("\n".join(summary_lines).rstrip())

        first = records[0]
        canonical_parts = []
        for field in assignments:
            value = first["values"].get(field)
            if value is None:
                continue
            canonical_parts.append(
                f"{self._canonical_preview_key(field)}-{value}"
            )

        canonical = (
            "_".join(canonical_parts) + first["path"].suffix
            if canonical_parts
            else "no metadata assigned"
        )
        self.preview_example_var.set(
            f"{first['path'].name}   →   {canonical}"
        )

