    def _refresh_categories(self):
        if (
            not hasattr(self, "category_options_frame")
            or not self.category_options_frame.winfo_exists()
        ):
            return

        active, custom = self._active_metadata()
        names = list(active.keys()) + list(custom.keys())

        for child in self.category_options_frame.winfo_children():
            child.destroy()

        active_set = set(names)

        # Remove stale category selector variables.
        for name in list(self.category_vars):
            if name in active_set:
                continue

            var = self.category_vars.pop(name)
            trace_id = self.category_trace_ids.pop(name, None)

            if trace_id is not None:
                try:
                    var.trace_remove("write", trace_id)
                except (tk.TclError, ValueError):
                    pass

        # Remove stale order state.
        for name in list(self.category_order_slots):
            if name not in active_set:
                self.category_order_slots.pop(name, None)
                self.category_order_observed.pop(name, None)

        if not names:
            if not self.category_empty_label.winfo_ismapped():
                self.category_empty_label.pack(fill="x", padx=4, pady=6)
            self._refresh_category_preview()
            return

        self.category_empty_label.pack_forget()
        _, _, records = self._preview_records()

        for name in names:
            if name not in self.category_vars:
                var = tk.BooleanVar(value=False)
                self.category_vars[name] = var
                self.category_trace_ids[name] = var.trace_add(
                    "write",
                    lambda *_: self._refresh_category_preview(),
                )

            var = self.category_vars[name]

            # ----------------------------------------------------------
            # Detect the actual values present in the current filenames.
            # ----------------------------------------------------------
            seen = set()
            observed = []

            for record in records:
                if name not in record["values"]:
                    continue

                value = str(record["values"][name])
                identity = value.casefold()

                if identity in seen:
                    continue

                seen.add(identity)
                observed.append(value)

            automatic = ordered_levels(
                observed,
                field_name=name,
                metadata_order=None,
            )

            previous_observed = self.category_order_observed.get(name, [])
            previous_slots = self.category_order_slots.get(name, [])

            same_values = (
                len(previous_observed) == len(automatic)
                and {value.casefold() for value in previous_observed}
                == {value.casefold() for value in automatic}
            )

            if not same_values or len(previous_slots) != len(automatic):
                # Dataset/metadata changed: create exactly one blank slot
                # for each detected value.
                slots = [
                    tk.StringVar(value="")
                    for _ in automatic
                ]
                self.category_order_slots[name] = slots
                self.category_order_observed[name] = list(automatic)
            else:
                slots = previous_slots
                self.category_order_observed[name] = list(automatic)

                valid = {value.casefold() for value in automatic}
                for slot_var in slots:
                    current = slot_var.get().strip()
                    if current and current.casefold() not in valid:
                        slot_var.set("")

            # ----------------------------------------------------------
            # Card header: checkbox + metadata name + detected count.
            # ----------------------------------------------------------
            row_card = RoundedCard(
                self.category_options_frame,
                fill=CARD_SOFT,
                outline=BORDER,
                radius=13,
                outer_bg=CARD,
                inset=3,
            )
            row_card.pack(fill="x", pady=4)
            card = row_card.content

            header = tk.Frame(card, bg=CARD_SOFT)
            header.pack(fill="x")

            ArcadeCheckBox(
                header,
                var,
                accent=ORANGE,
            ).pack(side="left", padx=(10, 8), pady=8)

            tk.Label(
                header,
                text=humanize(name),
                fg=TEXT,
                bg=CARD_SOFT,
                font=FONT_BODY,
                anchor="w",
            ).pack(side="left", fill="x", expand=True)

            if automatic:
                detected_text = (
                    f"{len(automatic)} detected value"
                    f"{'s' if len(automatic) != 1 else ''}"
                )
            else:
                detected_text = "No values detected"

            tk.Label(
                header,
                text=detected_text,
                fg=TEXT_DIM,
                bg=CARD_SOFT,
                font=FONT_SMALL,
            ).pack(side="right", padx=(8, 12))

            if not automatic:
                continue

            # ----------------------------------------------------------
            # Preferred-order slots.
            #
            # One readonly blank box is created per detected value.
            # The user fills them left -> right if an override is wanted.
            # Blank remainder = automatic ordering for the remainder.
            # ----------------------------------------------------------
            order_row = tk.Frame(card, bg=CARD_SOFT)
            order_row.pack(
                fill="x",
                padx=(54, 10),
                pady=(0, 9),
            )

            hint = (
                "Preferred order · optional · blank = numeric automatic"
                if normalize_metadata_field(name) == "timepoint"
                else "Preferred order · optional · blank = automatic"
            )

            tk.Label(
                order_row,
                text=hint,
                fg=TEXT_DIM,
                bg=CARD_SOFT,
                font=FONT_SMALL,
                anchor="w",
            ).pack(side="left", padx=(0, 10))

            slots_outer = tk.Frame(order_row, bg=CARD_SOFT)
            slots_outer.pack(side="left", fill="x", expand=True)

            # Wrap after six slots so fields with many levels (e.g. subject)
            # do not make the Category card wider than the window.
            max_per_line = 6
            slot_width = min(
                14,
                max(
                    7,
                    max(len(value) for value in automatic) + 2,
                ),
            )

            for index, slot_var in enumerate(slots):
                slot_line = index // max_per_line
                slot_column = index % max_per_line

                slot_frame = tk.Frame(slots_outer, bg=CARD_SOFT)
                slot_frame.grid(
                    row=slot_line,
                    column=slot_column,
                    sticky="w",
                    padx=(0, 6),
                    pady=2,
                )

                tk.Label(
                    slot_frame,
                    text=f"{index + 1}",
                    fg=TEXT_DIM,
                    bg=CARD_SOFT,
                    font=FONT_SMALL,
                ).pack(side="left", padx=(0, 3))

                combo = ttk.Combobox(
                    slot_frame,
                    textvariable=slot_var,
                    values=("", *automatic),
                    state="readonly",
                    width=slot_width,
                    style="MG.TCombobox",
                )
                combo.pack(side="left")
                combo.bind(
                    "<<ComboboxSelected>>",
                    lambda _event, field=name, slot_index=index:
                        self._category_order_slot_selected(
                            field,
                            slot_index,
                        ),
                )

            ArcadeButton(
                order_row,
                text="Auto",
                command=lambda field=name: self._reset_category_order(field),
                accent=CARD_TINT,
                fg=TEXT_DIM,
                width=5,
                compact=True,
            ).pack(side="right", padx=(8, 0))

        self._refresh_category_preview()



    def _reset_category_order(self, field_name: str):
        for slot_var in self.category_order_slots.get(field_name, []):
            slot_var.set("")
        self._refresh_category_preview()

    def _category_order_slot_selected(
        self,
        field_name: str,
        slot_index: int,
    ):
        """
        Keep preferred-order slots valid without free-text validation.

        If the same detected value is selected in another slot, the older
        occurrence is cleared automatically. Therefore the GUI cannot create
        duplicate order entries.
        """
        slots = self.category_order_slots.get(field_name, [])

        if not (0 <= int(slot_index) < len(slots)):
            return

        selected = slots[int(slot_index)].get().strip()

        if selected:
            identity = selected.casefold()

            for index, slot_var in enumerate(slots):
                if index == int(slot_index):
                    continue

                if slot_var.get().strip().casefold() == identity:
                    slot_var.set("")

        self._refresh_category_preview()

    def _refresh_category_preview(self):
        if not hasattr(
            self,
            "category_preview_var",
        ):
            return

        fields = self._selected_categories()

        (
            images,
            assignments,
            records,
        ) = self._preview_records()

        if not fields:

            self.category_preview_var.set(
                "Select one or more metadata fields above"
            )

            self.category_summary_var.set(
                (
                    f"{len(images)} image file(s) found"
                    if images
                    else ""
                )
            )

            return

        format_label = " + ".join(
            humanize(
                field
            )
            for field
            in fields
        )

        if not images:

            self.category_preview_var.set(
                format_label
            )

            self.category_summary_var.set(
                "Choose an input folder to preview "
                "the resulting categories."
            )

            return

        counts = Counter()

        for record in records:

            values = record[
                "values"
            ]

            if all(
                field in values
                for field in fields
            ):

                combination = tuple(
                    str(
                        values[
                            field
                        ]
                    )
                    for field
                    in fields
                )

                counts[
                    combination
                ] += 1

        if not counts:

            self.category_preview_var.set(
                format_label
            )

            self.category_summary_var.set(
                "The selected category fields could not "
                "be read from the current filenames."
            )

            return

        # The preview uses the exact same ordering contract as final plots.
        metadata_order = self._preferred_metadata_order()

        ordered_combos = ordered_combinations(
            counts.keys(),
            field_names=fields,
            metadata_order=(
                metadata_order
            ),
            comparison_oriented=True,
        )

        ordered = [
            (
                "-".join(
                    combination
                ),
                counts[
                    combination
                ],
            )
            for combination
            in ordered_combos
        ]

        example = ordered[
            0
        ][
            0
        ]

        self.category_preview_var.set(
            example
        )

        summary = "   ·   ".join(
            (
                f"{category}: {count} "
                f"file{'s' if count != 1 else ''}"
            )
            for (
                category,
                count,
            )
            in ordered[
                :10
            ]
        )

        if len(
            ordered
        ) > 10:

            summary += (
                f"   ·   +{len(ordered) - 10} "
                "more categories"
            )

        self.category_summary_var.set(
            (
                f"Defined by {format_label}\n"
                f"{len(counts)} "
                f"categor{'y' if len(counts) == 1 else 'ies'} "
                f"across {sum(counts.values())} matched files\n"
                f"{summary}"
            )
        )

